//! Reference compatibility test for `Qwen3Embedder` (CP7 / F6).
//!
//! Validates that the Candle-backed `Qwen3Embedder` produces embeddings matching
//! reference vectors generated by Hugging Face transformers/PyTorch for the pinned
//! `Qwen/Qwen3-Embedding-0.6B` revision (`97b0c614be4d77ee51c0cef4e5f07c00f9eb65b3`).
//!
//! Verifies:
//! - Exact cosine similarity >= 0.999 across all dimensions (1024, 768, 512)
//! - Query instruction formatting vs raw document embedding
//! - Batch embedding equivalence
//! - Proper L2 normalization and Matryoshka dimension truncation

use std::path::{Path, PathBuf};
use serde::Deserialize;

use attic_semantic::provider::{EmbeddingExecutionBudget, EmbeddingInput, EmbeddingProvider};
use attic_semantic::qwen3_provider::{Qwen3Embedder, QwenPooling};

const PINNED_REVISION: &str = "97b0c614be4d77ee51c0cef4e5f07c00f9eb65b3";
const MIN_COSINE_SIMILARITY: f32 = 0.999;

#[derive(Debug, Deserialize)]
struct Fixture {
    #[allow(dead_code)]
    model_id: String,
    model_revision: String,
    cases: Vec<TestCase>,
}

#[derive(Debug, Deserialize)]
struct TestCase {
    name: String,
    is_query: bool,
    text: String,
    #[allow(dead_code)]
    token_count: usize,
    vector_1024: Vec<f32>,
    vector_768: Vec<f32>,
    vector_512: Vec<f32>,
}

fn resolve_cache_dir() -> PathBuf {
    if let Ok(hf_home) = std::env::var("HF_HOME") {
        let p = PathBuf::from(hf_home).join("hub");
        if p.exists() {
            return p;
        }
    }
    if let Ok(home) = std::env::var("USERPROFILE").or_else(|_| std::env::var("HOME")) {
        let p = PathBuf::from(home).join(".cache").join("huggingface").join("hub");
        if p.exists() {
            return p;
        }
    }
    PathBuf::from(".cache/huggingface/hub")
}

fn cosine_similarity(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(a.len(), b.len(), "vector lengths must match for cosine similarity");
    let dot: f32 = a.iter().zip(b.iter()).map(|(x, y)| x * y).sum();
    let norm_a: f32 = a.iter().map(|x| x * x).sum::<f32>().sqrt();
    let norm_b: f32 = b.iter().map(|x| x * x).sum::<f32>().sqrt();
    dot / (norm_a * norm_b)
}

fn load_fixture() -> Fixture {
    let fixture_path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("qwen3_embedding_0_6b_reference.json");
    let content = std::fs::read_to_string(&fixture_path)
        .unwrap_or_else(|e| panic!("failed to read fixture at {}: {e}", fixture_path.display()));
    serde_json::from_str(&content).expect("failed to parse reference fixture JSON")
}

#[test]
fn test_qwen3_reference_compatibility_all_dimensions() {
    let fixture = load_fixture();
    assert_eq!(fixture.model_revision, PINNED_REVISION);
    assert!(!fixture.cases.is_empty());

    let cache_dir = resolve_cache_dir();
    let budget = EmbeddingExecutionBudget::default();

    for &dim in &[1024, 768, 512] {
        println!("Testing Qwen3 dimension override: {dim}...");
        let embedder = Qwen3Embedder::new_pinned(
            &cache_dir,
            8,
            PINNED_REVISION,
            Some(dim),
            QwenPooling::LastToken,
        )
        .expect("failed to instantiate Qwen3Embedder with pinned revision");

        assert_eq!(embedder.dimension(), dim);

        for case in &fixture.cases {
            let actual = if case.is_query {
                embedder
                    .embed_query(&case.text, &budget)
                    .unwrap_or_else(|e| panic!("embed_query failed for {}: {e}", case.name))
            } else {
                let inputs = vec![EmbeddingInput {
                    unit_key: case.name.clone(),
                    text: case.text.clone(),
                }];
                let outputs = embedder
                    .embed_documents(&inputs, &budget)
                    .unwrap_or_else(|e| panic!("embed_documents failed for {}: {e}", case.name));
                assert_eq!(outputs.len(), 1);
                outputs[0].vector.clone()
            };

            assert_eq!(
                actual.len(),
                dim,
                "Case '{}' produced wrong dimensionality",
                case.name
            );

            // Verify L2 unit norm
            let norm: f32 = actual.iter().map(|v| v * v).sum::<f32>().sqrt();
            assert!(
                (norm - 1.0).abs() < 1e-4,
                "Case '{}' vector is not unit normalized: norm={}",
                case.name,
                norm
            );

            let expected = match dim {
                1024 => &case.vector_1024,
                768 => &case.vector_768,
                512 => &case.vector_512,
                _ => unreachable!(),
            };

            let sim = cosine_similarity(&actual, expected);
            println!(
                "  dim={dim} case={:<22} is_query={:<5} cosine_sim={:.6}",
                case.name, case.is_query, sim
            );

            assert!(
                sim >= MIN_COSINE_SIMILARITY,
                "Case '{}' similarity {} below threshold {} for dim {}",
                case.name,
                sim,
                MIN_COSINE_SIMILARITY,
                dim
            );
        }
    }
}

#[test]
fn test_qwen3_batch_equivalence() {
    let fixture = load_fixture();
    let cache_dir = resolve_cache_dir();
    let budget = EmbeddingExecutionBudget::default();

    let embedder = Qwen3Embedder::new_pinned(
        &cache_dir,
        4, // batch size 4 forces multiple sub-batches
        PINNED_REVISION,
        Some(768),
        QwenPooling::LastToken,
    )
    .expect("failed to instantiate Qwen3Embedder");

    let doc_cases: Vec<&TestCase> = fixture.cases.iter().filter(|c| !c.is_query).collect();

    // Embed individually
    let mut individual_vectors = Vec::new();
    for case in &doc_cases {
        let input = vec![EmbeddingInput {
            unit_key: case.name.clone(),
            text: case.text.clone(),
        }];
        let out = embedder.embed_documents(&input, &budget).unwrap();
        individual_vectors.push(out[0].vector.clone());
    }

    // Embed all at once in batch
    let batch_inputs: Vec<EmbeddingInput> = doc_cases
        .iter()
        .map(|c| EmbeddingInput {
            unit_key: c.name.clone(),
            text: c.text.clone(),
        })
        .collect();

    let batch_outputs = embedder.embed_documents(&batch_inputs, &budget).unwrap();
    assert_eq!(batch_outputs.len(), individual_vectors.len());

    for (i, (ind, batch)) in individual_vectors.iter().zip(&batch_outputs).enumerate() {
        assert_eq!(batch.unit_key, doc_cases[i].name);
        let sim = cosine_similarity(ind, &batch.vector);
        assert!(
            sim >= 0.9999,
            "Batch item {} ('{}') diverged from individual embedding: cosine={sim}",
            i,
            batch.unit_key
        );
    }
}

#[test]
fn test_real_qwen3_cpu_isolation_dynamic_scaling_8_4_2_6() {
    use std::sync::Arc;
    use attic_semantic::cpu_isolation::CpuIsolationPlan;
    use attic_semantic::model_lifecycle::SharedModelHandle;

    let cache_dir = resolve_cache_dir();
    let embedder = Qwen3Embedder::new_pinned(
        &cache_dir,
        4,
        PINNED_REVISION,
        Some(512),
        QwenPooling::LastToken,
    )
    .expect("failed to load real Qwen3 embedder");

    // Single shared model handle managing the real loaded Qwen model
    let handle = Arc::new(SharedModelHandle::new(Arc::new(embedder), 1200, 8));

    // Dynamic orchestrator grant progression: 8 -> 4 -> 2 -> 6
    let grant_sequence = [8, 4, 2, 6];
    let requested_lanes = 4;
    let budget = EmbeddingExecutionBudget::default();

    for granted_threads in grant_sequence {
        let plan = CpuIsolationPlan::compute(granted_threads, requested_lanes);
        assert!(!plan.is_oversubscribed());
        assert!(plan.total_allocated_threads <= granted_threads);

        // Dynamically adjust maximum inference lane capacity
        handle.update_max_concurrency(plan.inference_lanes);
        assert_eq!(handle.max_concurrency(), plan.inference_lanes);
        plan.apply_environment_hints();

        // Perform real Qwen inference under the dynamic plan
        let vec = handle
            .embed_query("fn authenticate_user(token: &str) -> bool", &budget)
            .expect("real Qwen inference failed under dynamic CPU isolation plan");

        assert_eq!(vec.len(), 512);
        assert!(vec.iter().all(|v| v.is_finite()));
        let norm = vec.iter().map(|v| v * v).sum::<f32>().sqrt();
        assert!((norm - 1.0).abs() < 1e-4);

        // Verify active inferences drain cleanly to 0
        assert_eq!(handle.active_inferences(), 0);
    }
}
